export type GatewayPayload = {
  to: string; template: string; variables: {
    customerName: string; garageName: string; registration: string; serviceDate: string;
    serviceStatus?: string; workNote?: string; promisedDelivery?: string;
  }; idempotencyKey: string;
};
export type Sender = (payload: GatewayPayload) => Promise<void>;

/** Submit a consent-based template to the configured gateway; retries require gateway idempotency support. */
export async function sendWhatsApp(payload: GatewayPayload) {
  if (!process.env.WHATSAPP_URL || !process.env.WHATSAPP_TOKEN) throw new Error('WhatsApp gateway is not configured');
  const url = new URL(process.env.WHATSAPP_URL);
  if (url.protocol !== 'https:' || url.username || url.password) throw new Error('WhatsApp gateway requires HTTPS without URL credentials');
  const response = await fetch(url, {
    method: 'POST', redirect: 'error', signal: AbortSignal.timeout(15000),
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${process.env.WHATSAPP_TOKEN}`, 'Idempotency-Key': payload.idempotencyKey },
    body: JSON.stringify(payload),
  });
  if (!response.ok) { await response.body?.cancel(); throw new Error(`Gateway HTTP ${response.status}`); }
  const result: unknown = await response.json();
  if (!result || typeof result !== 'object' || !('accepted' in result) || result.accepted !== true) throw new Error('Gateway did not confirm acceptance');
}

/** Claim one due reminder under the garage lock, with consent and newer-service checks. */
async function claim(pool: Pool, now: Date) {
  return transaction(pool, async db => {
    const config = await settings(db);
    const cutoff = garageDate(new Date(now.getTime() + config.reminderDaysBefore * 86400000));
    const stale = new Date(now.getTime() - 10 * 60000).toISOString();
    const result = await db.query<{ data: Reminder }>(`
      SELECT data FROM records WHERE kind='reminders'
      AND data->>'dueDate'<=$1 AND (
        (data->>'status' IN ('pending','failed') AND (data->>'attempts')::integer<5 AND data->>'nextAttempt'<=$2)
        OR (data->>'status'='sending' AND data->>'nextAttempt'<=$3)
      ) ORDER BY data->>'dueDate',id LIMIT 1`, [cutoff, now.toISOString(), stale]);
    const reminder = result.rows[0]?.data;
    if (!reminder) return null;
    const job = await get(db, 'jobs', reminder.jobId);
    const vehicle = job && await get(db, 'bikes', job.bikeId);
    const customer = vehicle && await get(db, 'customers', vehicle.customerId);
    if (!job || !vehicle || !customer) throw new Error('Reminder references missing service data');
    const newer = await db.query<{ data: Job }>("SELECT data FROM records WHERE kind='jobs' AND data->>'bikeId'=$1 AND data->>'status'='completed'", [vehicle.id]);
    const isStatus = reminder.purpose === 'service_status';
    const superseded = isStatus
      ? job.timeline?.[job.timeline.length - 1]?.id !== reminder.eventId
      : newer.rows.some(row => row.data.id !== job.id && row.data.serviceDate > job.serviceDate);
    if (!customer.whatsappConsent || superseded || reminder.attempts >= 5) {
      await save(db, 'reminders', { ...reminder, status: 'skipped', error: reminder.attempts >= 5 ? 'Maximum attempts reached' : 'Consent withdrawn or newer service/update recorded' });
      return { skipped: true } as const;
    }
    await save(db, 'reminders', { ...reminder, status: 'sending', attempts: reminder.attempts + 1, nextAttempt: now.toISOString() });
    return {
      skipped: false, reminder,
      payload: { to: customer.phone, template: isStatus ? process.env.WHATSAPP_STATUS_TEMPLATE || 'bike_service_status' : process.env.WHATSAPP_TEMPLATE || 'bike_service_due',
        variables: {
          customerName: customer.name, garageName: config.name, registration: vehicle.registration,
          serviceDate: isStatus ? job.serviceDate : reminder.dueDate,
          ...(isStatus ? { serviceStatus: reminder.stage!.replaceAll('_', ' '), workNote: reminder.note || '',
            promisedDelivery: reminder.promisedDelivery || 'Not scheduled' } : {}),
        },
        idempotencyKey: reminder.id },
    } as const;
  });
}

/** Process a bounded batch; run from a five-minute cron rather than an always-on polling loop. */
export async function runReminders(pool: Pool, sender: Sender = sendWhatsApp, fixedNow?: Date) {
  if (process.env.REMINDERS_ENABLED !== 'true') return { enabled: false, processed: 0, failed: 0 };
  if (sender === sendWhatsApp && (!process.env.WHATSAPP_URL || !process.env.WHATSAPP_TOKEN)) throw new Error('Enabled reminders require WhatsApp configuration');
  let processed = 0, failed = 0;
  for (let i = 0; i < 50; i++) {
    const now = fixedNow || new Date();
    const claimed = await claim(pool, now);
    if (!claimed) break;
    processed++;
    if (claimed.skipped) continue;
    let sendError: string | null = null;
    try { await sender(claimed.payload); }
    catch (error) {
      failed++;
      // Keep provider/customer response bodies out of persisted errors and logs.
      sendError = error instanceof Error && /^Gateway HTTP \d+$/.test(error.message) ? error.message : 'Gateway rejected, timed out or returned an invalid response';
    }
    await transaction(pool, async db => {
      const current = await get(db, 'reminders', claimed.reminder.id);
      if (!current) throw new Error('Claimed reminder no longer exists');
      await save(db, 'reminders', { ...current, status: sendError ? 'failed' : 'sent', error: sendError,
        sentAt: sendError ? null : now.toISOString(),
        nextAttempt: new Date(now.getTime() + Math.min(24 * 60, 5 * 2 ** current.attempts) * 60000).toISOString() });
    });
  }
  return { enabled: true, processed, failed };
}
